<?php
use App\Http\Controllers\Api\AuthController; use App\Http\Controllers\Api\DatabaseHealthController; use App\Http\Controllers\Api\HealthController; use App\Http\Controllers\Api\V1\VehicleController; use App\Http\Controllers\Api\Admin\UserController; use App\Http\Controllers\Api\Admin\CatalogController; use Illuminate\Support\Facades\Route;
Route::middleware('throttle:api')->group(function (): void { Route::get('/health',HealthController::class)->name('api.health'); Route::post('/login',[AuthController::class,'login'])->middleware('throttle:login')->name('api.login'); if(app()->environment(['local','testing']))Route::get('/database',DatabaseHealthController::class)->name('api.database'); Route::middleware('auth:sanctum')->group(function():void{Route::get('/me',[AuthController::class,'me']);Route::get('/access-check',fn()=>response()->json(['message'=>'Acceso autorizado.']))->middleware('permission:vehicles.view');Route::post('/logout',[AuthController::class,'logout']); Route::middleware('permission:accounts.manage')->prefix('users')->group(function(){Route::get('/',[UserController::class,'index']);Route::post('/',[UserController::class,'store']);Route::get('/{user}',[UserController::class,'show']);Route::put('/{user}',[UserController::class,'update']);Route::patch('/{user}/role',[UserController::class,'updateRole']);});Route::middleware('permission:catalogs.manage')->prefix('catalogs/{type}')->whereIn('type',['brands','categories','models'])->group(function(){Route::get('/',[CatalogController::class,'index']);Route::post('/',[CatalogController::class,'store']);Route::put('/{id}',[CatalogController::class,'update']);});Route::prefix('v1')->group(function(){Route::get('vehicles',[VehicleController::class,'index'])->middleware('permission:vehicles.view');Route::get('vehicles/{vehicle}',[VehicleController::class,'show'])->middleware('permission:vehicles.view');Route::post('vehicles',[VehicleController::class,'store'])->middleware('permission:vehicles.create');});});});